using System;using System.Linq;using System.Collections.Generic;using System.Reflection;using Sdt.Core;using Sdt.Core.Battle;
class PaymentBoundary {
 sealed class Host:BattleHost {public int Hp{get;set;}=30;public int MaxHp=>60;public int Atk=>4;public int SpellPower=>2;public string MyClass=>null;public string CharacterId=>"wu";public IReadOnlyList<OwnedCard> OwnedCards{get;set;}public void Log(string t,string k=null){}public void Heal(int n){}public void OnBattleEnd(BattleResult r){} }
 static int passed;static void Check(bool ok,string label){if(!ok)throw new Exception(label);passed++;}
 static object Field(BattleSession b,string n)=>typeof(BattleSession).GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(b);
 static void Set(BattleSession b,string n,object v)=>typeof(BattleSession).GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(b,v);
 static CardDef Card(string id)=>CardLibrary.FindById(id).Clone();
 static BattleSession Start(params CardDef[] cards){var b=new BattleSession();b.Start(new BattleStartContext{host=new Host{OwnedCards=cards.Select((c,i)=>new OwnedCard{uid="o"+i,card=c}).ToArray()},rng=new Rng(123),enemies=new[]{new EnemyInput{id="f",name="目标",hp=100,atk=2}}});return b;}
 static RuleHandSelectionSnapshot Begin(BattleSession b){Check(b.PlayCard("o0",0,false).Ok,"payment entered");return b.Snapshot.RuleHandSelection;}
 static void Main(){CardLibrary.Init(()=>CardDatabase.All);
  var grudge=Card("tt7-thundergrudge");var starter=Card("starter-attack");
  var b=Start(grudge,starter,starter.Clone());var p=Begin(b);Check(p.act=="payment"&&p.n==2&&!p.canCancel,"mandatory payment shape");Check(!p.candidateUids.Contains("o0"),"source excluded");Check(b.Snapshot.Energy==2&&b.Snapshot.Hand.Count==3,"no precharge");Check(!b.SelectRuleHand("o1").Ok&&b.Snapshot.Hand.Count==3,"click cannot commit payment");Check(!b.ConfirmRuleHandPayment(p.selectionId,new[]{"o1"}).Ok&&b.Snapshot.RuleHandSelection!=null,"incomplete retains selection");Check(!b.ConfirmRuleHandPayment(p.selectionId+1,new[]{"o1","o2"}).Ok,"stale selection rejected");Check(b.ConfirmRuleHandPayment(p.selectionId,new[]{"o1","o2"}).Ok,"confirmed");Check(b.Snapshot.Foes[0].Hp==88&&b.Snapshot.Energy==1,"three attack segments once");Check(((List<string>)Field(b,"played")).SequenceEqual(new[]{"o0"}),"materials never played");Check((int)Field(b,"infusionTotal")==0,"payment never infusion");Check(!b.ConfirmRuleHandPayment(p.selectionId,new[]{"o1","o2"}).Ok&&b.Snapshot.Foes[0].Hp==88,"duplicate confirm rejected");b.Retract();
  b=Start(grudge,starter);Check(!b.PlayCard("o0",0,false).Ok&&b.Snapshot.RuleHandSelection==null&&b.Snapshot.Energy==2,"insufficient no selection no charge");b.Retract();
  foreach(string failure in new[]{"duplicate","source","energy","target","missing","changed"}){b=Start(grudge,starter,starter.Clone());p=Begin(b);string[] picked={"o1","o2"};if(failure=="duplicate")picked=new[]{"o1","o1"};if(failure=="source")picked=new[]{"o0","o1"};if(failure=="energy")Set(b,"energy",0);if(failure=="target")((List<BattleFoe>)Field(b,"foes"))[0].dead=true;if(failure=="missing")((List<string>)Field(b,"hand")).Remove("o2");if(failure=="changed")((Dictionary<string,CardDef>)Field(b,"cardOverrides"))["o2"]=Card("tt3-fireball");Check(!b.ConfirmRuleHandPayment(p.selectionId,picked).Ok,"revalidate "+failure);Check(((List<string>)Field(b,"consumed")).Count==0&&((List<string>)Field(b,"played")).Count==0,"atomic failure "+failure);b.Retract();}
  var custom=grudge.Clone();custom.id="custom-infused-pay";custom.infuse=1;custom.desc="注能(1)。";b=Start(custom,starter,starter.Clone(),starter.Clone());Check(!b.PlayCard("o0",0,false).Ok&&b.Snapshot.Infusing!=null,"infusion owner opens");b.SelectInfusion("o1");b.ConfirmInfusion(0);p=b.Snapshot.RuleHandSelection;Check(p!=null&&!p.candidateUids.Contains("o1")&&!p.candidateUids.Contains("o0"),"fuel and source excluded");Check(b.Snapshot.Energy==2&&((List<string>)Field(b,"consumed")).Count==0,"fuel also held until payment");Check(b.ConfirmRuleHandPayment(p.selectionId,new[]{"o2","o3"}).Ok,"fuel payment committed");Check((int)Field(b,"infusionTotal")==1,"only infusion fuel counts");b.Retract();
  b=Start(grudge,starter,starter.Clone());p=Begin(b);long prior=p.selectionId;b.Retract();b.Start(new BattleStartContext{host=new Host{OwnedCards=new[]{new OwnedCard{uid="o0",card=grudge},new OwnedCard{uid="o1",card=starter},new OwnedCard{uid="o2",card=starter}}},enemies=new[]{new EnemyInput{id="f",name="目标",hp=100}},rng=new Rng(123)});p=Begin(b);Check(p.selectionId>prior&&!b.ConfirmRuleHandPayment(prior,new[]{"o1","o2"}).Ok,"restart selection ownership");b.Retract();
  b=Start(grudge,grudge.Clone(),starter,starter.Clone(),starter.Clone(),starter.Clone());p=Begin(b);Check(b.ConfirmRuleHandPayment(p.selectionId,new[]{"o2","o3"}).Ok,"first copy paid");long first=p.selectionId;Check(b.PlayCard("o1",0,false).Ok,"second copy queued");p=b.Snapshot.RuleHandSelection;Check(p.selectionId!=first&&!b.ConfirmRuleHandPayment(first,new[]{"o4","o5"}).Ok,"two payments do not cross ownership");Check(b.Snapshot.Energy==1&&b.Snapshot.Foes[0].Hp==88,"second payment remains uncharged");Check(b.ConfirmRuleHandPayment(p.selectionId,new[]{"o4","o5"}).Ok&&b.Snapshot.Energy==0&&b.Snapshot.Foes[0].Hp==76,"second copy resolves exactly once");b.Retract();
  b=Start(custom,starter,starter.Clone(),starter.Clone());b.PlayCard("o0",0,false);b.SelectInfusion("o1");b.ConfirmInfusion(0);p=b.Snapshot.RuleHandSelection;var blocked=starter.Clone();blocked.rules=RuleValue.Obj("version",1,"battle",RuleValue.Obj("fuelAllowed",false));((Dictionary<string,CardDef>)Field(b,"cardOverrides"))["o1"]=blocked;Check(!b.ConfirmRuleHandPayment(p.selectionId,new[]{"o2","o3"}).Ok&&((List<string>)Field(b,"consumed")).Count==0,"fuelAllowed change revalidated before any payment");b.Retract();
  Console.WriteLine("Payment boundary passed: "+passed);
 }
}
